import 'package:flutter/material.dart';import '../data/app_store.dart';import '../models/models.dart';import '../theme/operon_theme.dart';
class ActionsScreen extends StatefulWidget{final AppStore store;const ActionsScreen({super.key,required this.store});@override State<ActionsScreen> createState()=>_S();}
class _S extends State<ActionsScreen>{@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Pending actions')),body:ListView(children:widget.store.tasks.map((t)=>Card(margin:const EdgeInsets.symmetric(horizontal:16,vertical:6),child:ListTile(leading:Icon(t.state==ActionState.completed?Icons.check_circle:Icons.pending_actions,color:t.state==ActionState.completed?Colors.green:OperonTheme.teal),title:Text(t.title),subtitle:Text('${t.equipmentTag??'General'} · ${t.state.name}'),trailing:PopupMenuButton<ActionState>(onSelected:(s)=>setState(()=>widget.store.setTaskState(t,s)),itemBuilder:(_)=>ActionState.values.map((s)=>PopupMenuItem(value:s,child:Text(s.name))).toList())))).toList(),floatingActionButton:FloatingActionButton(onPressed:()=>_add(c),child:const Icon(Icons.add_task)));
void _add(BuildContext c){final x=TextEditingController(),tag=TextEditingController();showDialog(context:c,builder:(d)=>AlertDialog(title:const Text('New action'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:x,decoration:const InputDecoration(labelText:'Action')),const SizedBox(height:8),TextField(controller:tag,decoration:const InputDecoration(labelText:'Equipment tag (optional)'))]),actions:[FilledButton(onPressed:(){widget.store.addTask(x.text,tag:tag.text.trim().isEmpty?null:tag.text.trim());Navigator.pop(d);setState((){});},child:const Text('Add'))]));}}
